const text = '[{"name":"Ada","score":8},{"name":"Bo","score":4},{"name":"Cy","score":10}]';
function report(json) {
  const records = JSON.parse(json);
  if (!Array.isArray(records)) throw new Error('Expected an array');
  const passed = records.filter(item => typeof item.score === 'number' && item.score >= 7);
  return { names: passed.map(item => item.name), total: passed.reduce((sum, item) => sum + item.score, 0) };
}
const result = report(text);
console.log(result.names.join(','));
console.log(result.total);
